    public java.util.List<ErrorCompilador> errores = new java.util.ArrayList<>();

    public static final class Ambito {
        public final String nombre;
        public final long inicio;
        public final long fin;
        public final boolean esFuncion;

        private Ambito(String nombre, long inicio, long fin, boolean esFuncion) {
            this.nombre = nombre;
            this.inicio = inicio;
            this.fin = fin;
            this.esFuncion = esFuncion;
        }
    }

    public final List<Ambito> ambitos = new ArrayList<>();

    public static long posicion(int linea, int columna) {
        return ((long) linea << 32) | Integer.toUnsignedLong(columna);
    }

    private void registrarAmbito(String nombre, int lineaInicio, int columnaInicio,
                                 int lineaFin, int columnaFin, boolean esFuncion) {
        ambitos.add(new Ambito(nombre, posicion(lineaInicio, columnaInicio),
                              posicion(lineaFin, columnaFin), esFuncion));
    }


        private String nombreToken(int id) {
            for (java.lang.reflect.Field f : sym.class.getFields()) {
                try {
                    if (f.getType() == int.class && f.getInt(null) == id) {
                        return f.getName();
                    }
                } catch (IllegalAccessException e) { }
            }
            return "?" + id;
        }

        private String esperados() {
            java.util.List<String> nombres = new java.util.ArrayList<>();
            for (int id : expected_token_ids()) {
                nombres.add(nombreToken(id));
            }
            return String.join(", ", nombres);
        }

        @Override
        public void syntax_error(Symbol cur) {
            boolean eof = (cur.sym == sym.EOF);
            String desc = eof ? "Fin de archivo inesperado" : "Token inesperado";

            String esp = esperados();
            if (!esp.isEmpty()) {
                desc += ". Se esperaba: " + esp;
            }

            errores.add(new ErrorCompilador(
                "Sintáctico",
                eof ? "EOF" : String.valueOf(cur.value),
                desc,
                cur.left,
                cur.right));
        }

    @Override
    public void unrecovered_syntax_error(Symbol cur) throws Exception {
        errores.add(new ErrorCompilador(
            "Sintáctico",
            String.valueOf(cur.value),
            "No fue posible recuperarse del error",
            cur.left,
            cur.right));
    }


